insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','mcq','easy','Concrete is made by mixing cement, sand and gravel in the ratio 1 : 2 : 4 by volume. How much sand is needed for 14 m³ of the mix?','कंक्रीट सीमेंट, रेत और बजरी को आयतन के अनुसार 1 : 2 : 4 के अनुपात में मिलाकर बनता है। मिश्रण के 14 घन मीटर के लिए कितनी रेत चाहिए?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s03", "csat_order": 1}'::jsonb,'[{"id": "a", "body": "2 m³", "body_hi": "2 घन मीटर", "isCorrect": false}, {"id": "b", "body": "4 m³", "body_hi": "4 घन मीटर", "isCorrect": true}, {"id": "c", "body": "7 m³", "body_hi": "7 घन मीटर", "isCorrect": false}, {"id": "d", "body": "8 m³", "body_hi": "8 घन मीटर", "isCorrect": false}]'::jsonb,2.5,0.83,'The ratio has 1 + 2 + 4 = 7 parts, so each part is 14 ÷ 7 = 2 m³, and sand, 2 parts, is 4 m³. 2 m³ is the cement; 8 m³ is the gravel; 7 m³ halves the whole mix.','अनुपात में 1 + 2 + 4 = 7 भाग हैं, इसलिए हर भाग 14 ÷ 7 = 2 घन मीटर है, और रेत, 2 भाग, 4 घन मीटर है। 2 घन मीटर सीमेंट है; 8 घन मीटर बजरी है; 7 घन मीटर पूरे मिश्रण का आधा करता है।','csat-l4-s03-qa-rm-sand-for-concrete','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Number Theory','statement_based','medium','If 0 < a < b < 1, which of the following statements is/are always correct?','यदि 0 < a < b < 1, तो निम्नलिखित में से कौन-सा/से कथन हमेशा सही है/हैं?','{"statements": ["a² < b²", "1/a < 1/b"], "statements_hi": ["a² < b²", "1/a < 1/b"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s03", "csat_order": 2}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'1: both numbers are positive, and squaring keeps the order of positive numbers, so a² < b² -- always correct. 2: taking reciprocals of positive numbers reverses their order: a < b gives 1/a > 1/b (for example a = 1/4, b = 1/2 give 4 > 2). So 2 is never correct.','1: दोनों संख्याएँ धनात्मक हैं, और धनात्मक संख्याओं का वर्ग उनका क्रम बनाए रखता है, इसलिए a² < b² -- हमेशा सही। 2: धनात्मक संख्याओं के व्युत्क्रम लेने से उनका क्रम उलट जाता है: a < b से 1/a > 1/b मिलता है (जैसे a = 1/4, b = 1/2 से 4 > 2)। इसलिए 2 कभी सही नहीं।','csat-l4-s03-qa-nt-what-always-holds-for-0-a-b-1','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Puzzle Hybrid','mcq','medium','A man buys a bicycle for ₹6,000 and sells it for ₹7,000. He then buys it back for ₹8,000 and sells it again for ₹9,000. In thousands of rupees, what is his overall gain or loss?','एक व्यक्ति ₹6,000 में एक साइकिल ख़रीदकर ₹7,000 में बेचता है। फिर वह उसे ₹8,000 में वापस ख़रीदता है और ₹9,000 में फिर बेच देता है। हज़ार रुपये में उसका कुल लाभ या हानि क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s03", "csat_order": 3}'::jsonb,'[{"id": "a", "body": "₹1 thousand loss", "body_hi": "₹1 हज़ार हानि", "isCorrect": false}, {"id": "b", "body": "No profit, no loss", "body_hi": "न लाभ न हानि", "isCorrect": false}, {"id": "c", "body": "₹1 thousand profit", "body_hi": "₹1 हज़ार लाभ", "isCorrect": false}, {"id": "d", "body": "₹2 thousand profit", "body_hi": "₹2 हज़ार लाभ", "isCorrect": true}]'::jsonb,2.5,0.83,'Treat the two deals separately: bought at 6 and sold at 7 is a gain of 1; bought at 8 and sold at 9 is another gain of 1. In all he gains ₹2 thousand (he paid out 14 and took in 16). ₹1 thousand profit counts the ₹1,000 by which he bought back above his own selling price as a loss set against the two gains -- but that money was not lost, it bought the bicycle he then sold; the other answers have no basis.','दोनों सौदों को अलग देखिए: 6 में ख़रीदकर 7 में बेचना 1 का लाभ है; 8 में ख़रीदकर 9 में बेचना 1 का और लाभ। कुल मिलाकर उसे ₹2 हज़ार का लाभ होता है (उसने 14 दिए और 16 लिए)। ₹1 हज़ार लाभ उस ₹1,000 को, जितना ऊपर उसने अपने ही बिक्री मूल्य से वापस ख़रीदा, दोनों लाभों के सामने हानि मान लेता है -- पर वह धन खोया नहीं गया, उससे वह साइकिल ख़रीदी गई जिसे उसने फिर बेचा; बाक़ी उत्तरों का कोई आधार नहीं।','csat-l4-s03-qa-ph-buying-and-selling-the-same-item-twice','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Truth-Liar','mcq','hard','On an island every person either always tells the truth or always lies. A visitor asks two islanders, A and B, ''Is at least one of you a truth-teller?'' Each of them answers ''Yes.'' What can the visitor conclude?','एक द्वीप पर हर व्यक्ति या तो हमेशा सच बोलता है या हमेशा झूठ। एक आगंतुक दो द्वीपवासियों, A और B, से पूछता है, ''क्या तुममें से कम से कम एक सच बोलने वाला है?'' दोनों उत्तर देते हैं ''हाँ।'' आगंतुक क्या निष्कर्ष निकाल सकता है?','{"craft": "inference", "csat_set": "csat-l4-s03", "csat_order": 4}'::jsonb,'[{"id": "a", "body": "Both of them tell the truth, since a liar could never have answered ''Yes''.", "body_hi": "दोनों सच बोलते हैं, क्योंकि कोई झूठा कभी ''हाँ'' उत्तर नहीं दे सकता था।", "isCorrect": false}, {"id": "b", "body": "They are of the same kind, but which kind cannot be told.", "body_hi": "दोनों एक ही प्रकार के हैं, पर कौन-से, यह नहीं बताया जा सकता।", "isCorrect": true}, {"id": "c", "body": "Exactly one of them tells the truth, and the other is lying about it.", "body_hi": "उनमें से ठीक एक सच बोलता है, और दूसरा इस बारे में झूठ बोल रहा है।", "isCorrect": false}, {"id": "d", "body": "Both of them are liars, since the question invites a false reply.", "body_hi": "दोनों झूठे हैं, क्योंकि प्रश्न ही झूठे उत्तर को न्योता देता है।", "isCorrect": false}]'::jsonb,2.5,0.83,'If exactly one were a truth-teller, the honest answer would be ''Yes'' -- so the truth-teller says ''Yes'' but the liar says ''No''; they would not agree. If both tell the truth, both say ''Yes''. If both are liars, the honest answer is ''No'', so both say ''Yes''. So their agreement shows only that they are of the same kind: both truthful or both liars, and the question cannot tell which. Each of ''both tell the truth'' and ''both are liars'' picks one of two possibilities.','यदि ठीक एक सच बोलने वाला होता, तो सच्चा उत्तर ''हाँ'' होता -- इसलिए सच बोलने वाला ''हाँ'' कहता पर झूठा ''नहीं''; वे सहमत न होते। यदि दोनों सच बोलते हैं, तो दोनों ''हाँ'' कहते हैं। यदि दोनों झूठे हैं, तो सच्चा उत्तर ''नहीं'' है, इसलिए दोनों ''हाँ'' कहते हैं। अतः उनकी सहमति केवल यह दिखाती है कि वे एक ही प्रकार के हैं: दोनों सच्चे या दोनों झूठे, और प्रश्न से यह पता नहीं चलता कि कौन-से। ''दोनों सच बोलते हैं'' और ''दोनों झूठे हैं'' दो संभावनाओं में से केवल एक चुनते हैं।','csat-l4-s03-lr-tl-two-islanders-who-give-the-same-answer','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Sequences & Series','mcq','medium','What is the next number in the series 1, 2, 2, 4, 8, 32, ...?','श्रेणी 1, 2, 2, 4, 8, 32, ... की अगली संख्या क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s03", "csat_order": 5}'::jsonb,'[{"id": "a", "body": "64", "body_hi": "64", "isCorrect": false}, {"id": "b", "body": "128", "body_hi": "128", "isCorrect": false}, {"id": "c", "body": "256", "body_hi": "256", "isCorrect": true}, {"id": "d", "body": "512", "body_hi": "512", "isCorrect": false}]'::jsonb,2.5,0.83,'After the first two, each term is the product of the two before it: 1 × 2 = 2, 2 × 2 = 4, 2 × 4 = 8, 4 × 8 = 32, and so the next is 8 × 32 = 256. 64 doubles the last term; 128 multiplies it by 4; 512 multiplies it by 16.','पहले दो के बाद हर पद अपने से पहले के दो पदों का गुणनफल है: 1 × 2 = 2, 2 × 2 = 4, 2 × 4 = 8, 4 × 8 = 32, और इसलिए अगला 8 × 32 = 256 है। 64 अंतिम पद को दोगुना करता है; 128 उसे 4 से गुणा करता है; 512 उसे 16 से।','csat-l4-s03-qa-ss-a-series-of-products','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In Plato''s Republic a character tells of a shepherd who finds a ring that makes him invisible, and who uses it to do as he pleases without fear of being caught. The story poses a hard question: would anyone stay honest who could never be found out? If people are just only because they fear being seen, then honesty is merely prudence. Most of us hope that our integrity runs deeper than that, and much of public life depends on it, since no inspector can watch every official at every moment. Yet a sensible society does not stake everything on that hope. It also arranges things so that honesty is easier and dishonesty riskier -- open records, rotation of duties, decisions that leave a trace -- so that decent conduct does not require heroes.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
प्लेटो के ''रिपब्लिक'' में एक पात्र ऐसे चरवाहे की कथा सुनाता है जिसे एक अँगूठी मिलती है जो उसे अदृश्य कर देती है, और जो उसका प्रयोग पकड़े जाने के डर के बिना मनमानी करने के लिए करता है। कथा एक कठिन प्रश्न उठाती है: क्या कोई ऐसा व्यक्ति ईमानदार रहेगा जिसे कभी पकड़ा न जा सके? यदि लोग केवल देखे जाने के डर से न्यायपूर्ण हैं, तो ईमानदारी केवल चतुराई है। हममें से अधिकांश आशा करते हैं कि हमारी सत्यनिष्ठा इससे गहरी है, और सार्वजनिक जीवन का बहुत कुछ इसी पर निर्भर है, क्योंकि कोई निरीक्षक हर अधिकारी को हर क्षण नहीं देख सकता। फिर भी एक समझदार समाज सब कुछ इसी आशा पर दाँव पर नहीं लगाता। वह ऐसी व्यवस्था भी करता है कि ईमानदारी आसान और बेईमानी जोखिम भरी हो -- खुले अभिलेख, कर्तव्यों का बारी-बारी से बदलना, ऐसे निर्णय जो निशान छोड़ें -- ताकि अच्छे आचरण के लिए नायकों की आवश्यकता न पड़े।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s03", "passage_group": "csat-l4-s03-p01", "csat_order": 6}'::jsonb,'[{"id": "a", "body": "People are honest only because they fear being caught, as the story of the ring shows clearly.", "body_hi": "लोग केवल इसलिए ईमानदार हैं कि उन्हें पकड़े जाने का डर है, जैसा अँगूठी की कथा स्पष्ट दिखाती है।", "isCorrect": false}, {"id": "b", "body": "Integrity matters most when no one is watching, but society should not rely on it alone.", "body_hi": "सत्यनिष्ठा तब सबसे अधिक मायने रखती है जब कोई देख न रहा हो, पर समाज अकेले उस पर निर्भर न रहे।", "isCorrect": true}, {"id": "c", "body": "Every public official should be watched at every moment so that no one can act unseen.", "body_hi": "हर सार्वजनिक अधिकारी पर हर क्षण नज़र रखी जाए ताकि कोई भी बिना देखे काम न कर सके।", "isCorrect": false}, {"id": "d", "body": "The story of the ring proves that no one could remain honest if they could never be caught.", "body_hi": "अँगूठी की कथा सिद्ध करती है कि कोई भी ईमानदार नहीं रह सकता यदि उसे कभी पकड़ा न जा सके।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage values integrity that does not depend on being watched, since public life relies on it, but adds that a sensible society also makes honesty easier and dishonesty riskier rather than relying on that integrity alone. It does not say people are honest only out of fear -- it hopes integrity runs deeper; it does not want every official watched, which it calls impossible; and it treats the shepherd''s story as a question, not as proof that honesty is impossible.','परिच्छेद ऐसी सत्यनिष्ठा को महत्त्व देता है जो देखे जाने पर निर्भर न हो, क्योंकि सार्वजनिक जीवन उस पर टिका है, पर जोड़ता है कि समझदार समाज अकेले उस सत्यनिष्ठा पर निर्भर रहने के बजाय ईमानदारी को आसान और बेईमानी को जोखिम भरा भी बनाता है। वह यह नहीं कहता कि लोग केवल डर से ईमानदार हैं -- वह आशा करता है कि सत्यनिष्ठा गहरी है; वह हर अधिकारी पर नज़र रखना नहीं चाहता, जिसे वह असंभव कहता है; और वह चरवाहे की कथा को एक प्रश्न मानता है, इस बात का प्रमाण नहीं कि ईमानदारी असंभव है।','csat-l4-s03-rc-p01-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In Plato''s Republic a character tells of a shepherd who finds a ring that makes him invisible, and who uses it to do as he pleases without fear of being caught. The story poses a hard question: would anyone stay honest who could never be found out? If people are just only because they fear being seen, then honesty is merely prudence. Most of us hope that our integrity runs deeper than that, and much of public life depends on it, since no inspector can watch every official at every moment. Yet a sensible society does not stake everything on that hope. It also arranges things so that honesty is easier and dishonesty riskier -- open records, rotation of duties, decisions that leave a trace -- so that decent conduct does not require heroes.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
प्लेटो के ''रिपब्लिक'' में एक पात्र ऐसे चरवाहे की कथा सुनाता है जिसे एक अँगूठी मिलती है जो उसे अदृश्य कर देती है, और जो उसका प्रयोग पकड़े जाने के डर के बिना मनमानी करने के लिए करता है। कथा एक कठिन प्रश्न उठाती है: क्या कोई ऐसा व्यक्ति ईमानदार रहेगा जिसे कभी पकड़ा न जा सके? यदि लोग केवल देखे जाने के डर से न्यायपूर्ण हैं, तो ईमानदारी केवल चतुराई है। हममें से अधिकांश आशा करते हैं कि हमारी सत्यनिष्ठा इससे गहरी है, और सार्वजनिक जीवन का बहुत कुछ इसी पर निर्भर है, क्योंकि कोई निरीक्षक हर अधिकारी को हर क्षण नहीं देख सकता। फिर भी एक समझदार समाज सब कुछ इसी आशा पर दाँव पर नहीं लगाता। वह ऐसी व्यवस्था भी करता है कि ईमानदारी आसान और बेईमानी जोखिम भरी हो -- खुले अभिलेख, कर्तव्यों का बारी-बारी से बदलना, ऐसे निर्णय जो निशान छोड़ें -- ताकि अच्छे आचरण के लिए नायकों की आवश्यकता न पड़े।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["Once records are open and decisions leave a trace, the personal integrity of officials no longer matters.", "According to the passage, Plato concluded that people are honest only because they fear being seen."], "statements_hi": ["एक बार अभिलेख खुले हों और निर्णय निशान छोड़ें, तो अधिकारियों की निजी सत्यनिष्ठा का कोई महत्त्व नहीं रह जाता।", "परिच्छेद के अनुसार प्लेटो ने निष्कर्ष निकाला कि लोग केवल देखे जाने के डर से ईमानदार हैं।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s03", "passage_group": "csat-l4-s03-p01", "csat_order": 7}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": true}]'::jsonb,2.5,0.83,'Neither is valid. 1 goes beyond the passage: it recommends open records and similar arrangements to make honesty easier, but it never says that they make personal integrity unnecessary -- it calls public life dependent on that integrity. 2 also goes too far: the passage reports the story''s question without saying that Plato concluded that people are honest only from fear; it hopes integrity runs deeper.','कोई भी वैध नहीं। 1 परिच्छेद से आगे जाता है: वह ईमानदारी को आसान बनाने के लिए खुले अभिलेखों और ऐसी व्यवस्थाओं की सलाह देता है, पर कभी नहीं कहता कि वे निजी सत्यनिष्ठा को अनावश्यक बना देती हैं -- वह सार्वजनिक जीवन को उस सत्यनिष्ठा पर निर्भर बताता है। 2 भी बहुत आगे जाता है: परिच्छेद कथा का प्रश्न बताता है, यह नहीं कहता कि प्लेटो ने निष्कर्ष निकाला कि लोग केवल डर से ईमानदार हैं; वह आशा करता है कि सत्यनिष्ठा गहरी है।','csat-l4-s03-rc-p01-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','medium','What is the smallest whole number whose digits add up to 25?','वह सबसे छोटी पूर्ण संख्या कौन-सी है जिसके अंकों का योग 25 है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s03", "csat_order": 8}'::jsonb,'[{"id": "a", "body": "799", "body_hi": "799", "isCorrect": true}, {"id": "b", "body": "889", "body_hi": "889", "isCorrect": false}, {"id": "c", "body": "979", "body_hi": "979", "isCorrect": false}, {"id": "d", "body": "997", "body_hi": "997", "isCorrect": false}]'::jsonb,2.5,0.83,'Two digits can add up to at most 18, so at least three are needed. With three digits the number is smallest when the first digit is as small as possible, which means the last two are as large as possible: 9 and 9, leaving 25 - 18 = 7 for the first. So the answer is 799. 889, 979 and 997 also have digit sum 25, but each is larger than 799.','दो अंकों का योग अधिक से अधिक 18 हो सकता है, इसलिए कम से कम तीन अंक चाहिए। तीन अंकों में संख्या तब सबसे छोटी है जब पहला अंक जितना हो सके छोटा हो, यानी बाक़ी दो जितने हो सकें बड़े: 9 और 9, जिससे पहले के लिए 25 - 18 = 7 बचता है। अतः उत्तर 799 है। 889, 979 और 997 का अंक-योग भी 25 है, पर हर एक 799 से बड़ी है।','csat-l4-s03-qa-nt-the-smallest-number-with-digit-sum-25','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Cube Painting','mcq','hard','A large cube is made of 27 small cubes. Three square tunnels, each the width of one small cube, are cut straight through it from the centre of each face to the centre of the opposite face, removing every small cube that lies in their way. How many small cubes are left?','एक बड़ा घन 27 छोटे घनों से बना है। उसमें तीन वर्गाकार सुरंगें, हर एक एक छोटे घन की चौड़ाई की, हर फलक के केंद्र से सामने वाले फलक के केंद्र तक सीधी काटी जाती हैं, जिनके रास्ते में आने वाला हर छोटा घन हटा दिया जाता है। कितने छोटे घन बचते हैं?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s03", "csat_order": 9}'::jsonb,'[{"id": "a", "body": "18", "body_hi": "18", "isCorrect": false}, {"id": "b", "body": "19", "body_hi": "19", "isCorrect": false}, {"id": "c", "body": "20", "body_hi": "20", "isCorrect": true}, {"id": "d", "body": "21", "body_hi": "21", "isCorrect": false}]'::jsonb,2.5,0.83,'Each tunnel removes the three cubes in a line through the centre, but all three tunnels pass through the central cube. So the cubes removed are the centre and the six cubes at the centres of the faces: 7 in all, leaving 27 - 7 = 20 -- the 8 corner cubes and the 12 edge cubes. 18 subtracts 3 cubes for each tunnel, counting the centre three times; 19 counts it twice; 21 leaves out one face-centre cube.','हर सुरंग केंद्र से होकर जाती रेखा के तीन घन हटाती है, पर तीनों सुरंगें केंद्र वाले घन से गुज़रती हैं। इसलिए हटाए गए घन हैं केंद्र और फलकों के केंद्रों पर के छह घन: कुल 7, जिससे 27 - 7 = 20 बचते हैं -- 8 कोने वाले और 12 किनारे वाले घन। 18 हर सुरंग के लिए 3 घन घटाता है, केंद्र को तीन बार गिनकर; 19 उसे दो बार गिनता है; 21 फलक-केंद्र का एक घन छोड़ देता है।','csat-l4-s03-lr-cp-a-cube-drilled-through-its-faces','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','mcq','medium','In a 50-over cricket match, a team chasing 282 has scored at 4 runs an over in the first 10 overs without losing a wicket. At what average rate must it score in the remaining 40 overs to reach 282?','50 ओवर के एक क्रिकेट मैच में 282 का पीछा करती टीम ने पहले 10 ओवरों में बिना विकेट खोए 4 रन प्रति ओवर की दर से रन बनाए हैं। 282 तक पहुँचने के लिए उसे बाक़ी 40 ओवरों में किस औसत दर से रन बनाने होंगे?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s03", "csat_order": 10}'::jsonb,'[{"id": "a", "body": "5.50", "body_hi": "5.50", "isCorrect": false}, {"id": "b", "body": "5.64", "body_hi": "5.64", "isCorrect": false}, {"id": "c", "body": "6.05", "body_hi": "6.05", "isCorrect": true}, {"id": "d", "body": "7.05", "body_hi": "7.05", "isCorrect": false}]'::jsonb,2.5,0.83,'The team has 40 runs, so it needs 282 - 40 = 242 more in 40 overs: 242 ÷ 40 = 6.05 runs an over. 5.64 is 282 spread over all 50 overs; 7.05 spreads 282 over the last 40 alone, forgetting the runs already made; 5.50 has no basis.','टीम के 40 रन हैं, इसलिए उसे 40 ओवरों में 282 - 40 = 242 और चाहिए: 242 ÷ 40 = 6.05 रन प्रति ओवर। 5.64, 282 को सभी 50 ओवरों में बाँटता है; 7.05, पहले से बने रन भूलकर 282 को केवल अंतिम 40 ओवरों में बाँटता है; 5.50 का कोई आधार नहीं।','csat-l4-s03-qa-rm-a-required-run-rate','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Time & Work','mcq','medium','Three identical sprinklers together water a lawn in 4 hours. After they have been running for 1 hour, one of them breaks down, and the other two carry on. How long does it take to water the whole lawn?','तीन एक जैसे स्प्रिंकलर मिलकर एक लॉन को 4 घंटे में सींचते हैं। 1 घंटा चलने के बाद उनमें से एक ख़राब हो जाता है, और बाक़ी दो चलते रहते हैं। पूरे लॉन को सींचने में कितना समय लगता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s03", "csat_order": 11}'::jsonb,'[{"id": "a", "body": "4.5 hours", "body_hi": "4.5 घंटे", "isCorrect": false}, {"id": "b", "body": "5 hours", "body_hi": "5 घंटे", "isCorrect": false}, {"id": "c", "body": "5.5 hours", "body_hi": "5.5 घंटे", "isCorrect": true}, {"id": "d", "body": "6 hours", "body_hi": "6 घंटे", "isCorrect": false}]'::jsonb,2.5,0.83,'The lawn needs 3 × 4 = 12 sprinkler-hours. The first hour supplies 3 of them, leaving 9, which two sprinklers supply in 4.5 hours. The total is 1 + 4.5 = 5.5 hours. 4.5 hours forgets the first hour; 6 hours would be the time with two sprinklers from the start; 5 hours has no basis.','लॉन को 3 × 4 = 12 स्प्रिंकलर-घंटे चाहिए। पहला घंटा उनमें से 3 देता है, 9 बचते हैं, जिन्हें दो स्प्रिंकलर 4.5 घंटे में देते हैं। कुल 1 + 4.5 = 5.5 घंटे। 4.5 घंटे पहला घंटा भूल जाता है; 6 घंटे आरंभ से ही दो स्प्रिंकलर होने पर लगने वाला समय है; 5 घंटे का कोई आधार नहीं।','csat-l4-s03-qa-tw-sprinklers-when-one-breaks','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Most Indian enterprises are very small, many with fewer than ten workers, and a few are very large; comparatively few are of middling size. Economists call this the missing middle, and it matters because medium firms tend to be more productive than tiny ones and are where many better-paid jobs are created. Regulation is often blamed. For decades some labour rules began to bite only above a fixed number of workers -- permission to lay off workers, for instance, was needed by factories with a hundred or more -- and a firm near such a line had a reason to stay below it. Raising or removing such thresholds may help. But it would be a mistake to treat them as the whole story. Small firms also stay small because credit is hard to get, because their markets are local, and because their owners lack the managers needed to run something bigger.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
अधिकांश भारतीय उद्यम बहुत छोटे हैं, कई में दस से कम कामगार, और कुछ बहुत बड़े हैं; मध्यम आकार के अपेक्षाकृत कम हैं। अर्थशास्त्री इसे ''लुप्त मध्य'' कहते हैं, और यह इसलिए मायने रखता है कि मध्यम फ़र्में प्रायः बहुत छोटी फ़र्मों से अधिक उत्पादक होती हैं और वहीं बेहतर वेतन वाली कई नौकरियाँ बनती हैं। प्रायः विनियमन को दोष दिया जाता है। दशकों तक कुछ श्रम नियम एक निश्चित संख्या से अधिक कामगारों पर ही लागू होते थे -- उदाहरण के लिए, सौ या अधिक कामगारों वाले कारख़ानों को छँटनी के लिए अनुमति चाहिए थी -- और ऐसी रेखा के पास की फ़र्म के पास उससे नीचे बने रहने का कारण था। ऐसी सीमाओं को बढ़ाना या हटाना सहायक हो सकता है। पर उन्हें पूरी कहानी मानना भूल होगी। छोटी फ़र्में इसलिए भी छोटी रहती हैं कि ऋण पाना कठिन है, उनके बाज़ार स्थानीय हैं, और उनके मालिकों के पास किसी बड़े उद्यम को चलाने के लिए आवश्यक प्रबंधक नहीं हैं।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s03", "passage_group": "csat-l4-s03-p02", "csat_order": 12}'::jsonb,'[{"id": "a", "body": "Rules that bite above a size help explain the missing middle, but are not its only cause.", "body_hi": "आकार-सीमा के ऊपर लगने वाले नियम लुप्त मध्य को कुछ हद तक समझाते हैं, पर वे एकमात्र कारण नहीं।", "isCorrect": true}, {"id": "b", "body": "Labour rules have nothing to do with the small size of most Indian firms, whatever is often said.", "body_hi": "प्रायः जो भी कहा जाए, अधिकांश भारतीय फ़र्मों के छोटे आकार से श्रम नियमों का कोई संबंध नहीं है।", "isCorrect": false}, {"id": "c", "body": "India''s largest firms are the main reason why so few firms of middling size exist in the country.", "body_hi": "भारत की सबसे बड़ी फ़र्में ही वह मुख्य कारण हैं जिससे देश में मध्यम आकार की फ़र्में इतनी कम हैं।", "isCorrect": false}, {"id": "d", "body": "Removing the size thresholds in labour rules would on its own be enough to fill the missing middle.", "body_hi": "श्रम नियमों में आकार की सीमाएँ हटाना अपने आप में लुप्त मध्य को भरने के लिए पर्याप्त होगा।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage explains why the missing middle matters and why regulatory thresholds are blamed, then limits that explanation: thresholds are part of the story, alongside credit, local markets and managerial capacity. It says raising thresholds ''may help'', so it does not call them irrelevant; it does not say large firms are the problem; and it says removing thresholds is not the whole story, the opposite of its being enough on its own.','परिच्छेद बताता है कि लुप्त मध्य क्यों मायने रखता है और विनियामक सीमाओं को दोष क्यों दिया जाता है, फिर उस व्याख्या को सीमित करता है: सीमाएँ कहानी का एक भाग हैं, ऋण, स्थानीय बाज़ारों और प्रबंधकीय क्षमता के साथ। वह कहता है कि सीमाएँ बढ़ाना ''सहायक हो सकता है'', इसलिए वह उन्हें अप्रासंगिक नहीं कहता; वह बड़ी फ़र्मों को समस्या नहीं बताता; और वह कहता है कि सीमाएँ हटाना पूरी कहानी नहीं, जो अकेले उसके पर्याप्त होने का उलटा है।','csat-l4-s03-rc-p02-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Most Indian enterprises are very small, many with fewer than ten workers, and a few are very large; comparatively few are of middling size. Economists call this the missing middle, and it matters because medium firms tend to be more productive than tiny ones and are where many better-paid jobs are created. Regulation is often blamed. For decades some labour rules began to bite only above a fixed number of workers -- permission to lay off workers, for instance, was needed by factories with a hundred or more -- and a firm near such a line had a reason to stay below it. Raising or removing such thresholds may help. But it would be a mistake to treat them as the whole story. Small firms also stay small because credit is hard to get, because their markets are local, and because their owners lack the managers needed to run something bigger.

According to the reasoning of the passage, which one of the following firms is most likely to stay small even if every size threshold in labour rules were removed?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
अधिकांश भारतीय उद्यम बहुत छोटे हैं, कई में दस से कम कामगार, और कुछ बहुत बड़े हैं; मध्यम आकार के अपेक्षाकृत कम हैं। अर्थशास्त्री इसे ''लुप्त मध्य'' कहते हैं, और यह इसलिए मायने रखता है कि मध्यम फ़र्में प्रायः बहुत छोटी फ़र्मों से अधिक उत्पादक होती हैं और वहीं बेहतर वेतन वाली कई नौकरियाँ बनती हैं। प्रायः विनियमन को दोष दिया जाता है। दशकों तक कुछ श्रम नियम एक निश्चित संख्या से अधिक कामगारों पर ही लागू होते थे -- उदाहरण के लिए, सौ या अधिक कामगारों वाले कारख़ानों को छँटनी के लिए अनुमति चाहिए थी -- और ऐसी रेखा के पास की फ़र्म के पास उससे नीचे बने रहने का कारण था। ऐसी सीमाओं को बढ़ाना या हटाना सहायक हो सकता है। पर उन्हें पूरी कहानी मानना भूल होगी। छोटी फ़र्में इसलिए भी छोटी रहती हैं कि ऋण पाना कठिन है, उनके बाज़ार स्थानीय हैं, और उनके मालिकों के पास किसी बड़े उद्यम को चलाने के लिए आवश्यक प्रबंधक नहीं हैं।

परिच्छेद के तर्क के अनुसार, श्रम नियमों की हर आकार-सीमा हटा दिए जाने पर भी निम्नलिखित में से किस फ़र्म के छोटे बने रहने की सबसे अधिक संभावना है?','{"craft": "inference", "csat_set": "csat-l4-s03", "passage_group": "csat-l4-s03-p02", "csat_order": 13}'::jsonb,'[{"id": "a", "body": "A factory with 95 workers that has avoided hiring more only because of the lay-off rule", "body_hi": "95 कामगारों वाला कारख़ाना जिसने केवल छँटनी के नियम के कारण और भर्ती से परहेज़ किया है", "isCorrect": false}, {"id": "b", "body": "A firm whose sole reason for staying small is the paperwork it would face above a threshold", "body_hi": "ऐसी फ़र्म जिसके छोटे बने रहने का एकमात्र कारण सीमा के ऊपर होने वाली काग़ज़ी कार्यवाही है", "isCorrect": false}, {"id": "c", "body": "A workshop whose owner cannot borrow, sells only in his own town and has no managers", "body_hi": "ऐसी कार्यशाला जिसका मालिक ऋण नहीं ले सकता, केवल अपने नगर में बेचता है और जिसके पास प्रबंधक नहीं", "isCorrect": true}, {"id": "d", "body": "A firm with easy access to credit and buyers in many States that fears only labour rules", "body_hi": "ऐसी फ़र्म जिसे ऋण आसानी से मिलता है और कई राज्यों में ख़रीदार हैं, और जिसे केवल श्रम नियमों का डर है", "isCorrect": false}]'::jsonb,2.5,0.83,'Removing thresholds takes away only the regulatory reason to stay small. A firm whose owner cannot borrow, sells only in its own town and has no one to help manage a larger business still faces the other three obstacles the passage names. A firm held below a hundred workers by the lay-off rule, a firm whose only worry was the paperwork above a threshold, and a firm with ample credit and distant buyers would each be freed to grow once the thresholds went.','सीमाएँ हटाने से केवल छोटे रहने का विनियामक कारण हटता है। जिस फ़र्म का मालिक ऋण नहीं ले सकता, केवल अपने नगर में बेचता है और जिसके पास बड़े व्यवसाय को सँभालने में मदद करने वाला कोई नहीं, वह परिच्छेद में बताई अन्य तीनों बाधाओं का सामना करती रहती है। छँटनी के नियम के कारण सौ से कम कामगारों पर रुकी फ़र्म, ऐसी फ़र्म जिसकी एकमात्र चिंता सीमा के ऊपर की काग़ज़ी कार्यवाही थी, और पर्याप्त ऋण व दूर के ख़रीदारों वाली फ़र्म -- सीमाएँ हटते ही हर एक बढ़ने के लिए स्वतंत्र हो जाती।','csat-l4-s03-rc-p02-who-stays-small-without-thresholds','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Assumption','statement_based','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Most Indian enterprises are very small, many with fewer than ten workers, and a few are very large; comparatively few are of middling size. Economists call this the missing middle, and it matters because medium firms tend to be more productive than tiny ones and are where many better-paid jobs are created. Regulation is often blamed. For decades some labour rules began to bite only above a fixed number of workers -- permission to lay off workers, for instance, was needed by factories with a hundred or more -- and a firm near such a line had a reason to stay below it. Raising or removing such thresholds may help. But it would be a mistake to treat them as the whole story. Small firms also stay small because credit is hard to get, because their markets are local, and because their owners lack the managers needed to run something bigger.

Which of the following assumptions has/have been made in the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
अधिकांश भारतीय उद्यम बहुत छोटे हैं, कई में दस से कम कामगार, और कुछ बहुत बड़े हैं; मध्यम आकार के अपेक्षाकृत कम हैं। अर्थशास्त्री इसे ''लुप्त मध्य'' कहते हैं, और यह इसलिए मायने रखता है कि मध्यम फ़र्में प्रायः बहुत छोटी फ़र्मों से अधिक उत्पादक होती हैं और वहीं बेहतर वेतन वाली कई नौकरियाँ बनती हैं। प्रायः विनियमन को दोष दिया जाता है। दशकों तक कुछ श्रम नियम एक निश्चित संख्या से अधिक कामगारों पर ही लागू होते थे -- उदाहरण के लिए, सौ या अधिक कामगारों वाले कारख़ानों को छँटनी के लिए अनुमति चाहिए थी -- और ऐसी रेखा के पास की फ़र्म के पास उससे नीचे बने रहने का कारण था। ऐसी सीमाओं को बढ़ाना या हटाना सहायक हो सकता है। पर उन्हें पूरी कहानी मानना भूल होगी। छोटी फ़र्में इसलिए भी छोटी रहती हैं कि ऋण पाना कठिन है, उनके बाज़ार स्थानीय हैं, और उनके मालिकों के पास किसी बड़े उद्यम को चलाने के लिए आवश्यक प्रबंधक नहीं हैं।

परिच्छेद में निम्नलिखित में से कौन-सी पूर्वधारणा/एँ बनाई गई है/हैं?','{"statements": ["Every large firm is more productive than every small one.", "Firms take into account the costs that a rule would impose on them when deciding whether to grow."], "statements_hi": ["हर बड़ी फ़र्म हर छोटी फ़र्म से अधिक उत्पादक है।", "फ़र्में बढ़ने का निर्णय लेते समय उन लागतों का ध्यान रखती हैं जो कोई नियम उन पर डालेगा।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s03", "passage_group": "csat-l4-s03-p02", "csat_order": 14}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 2 is assumed. The claim that a firm near a threshold ''had a reason to stay below it'' takes for granted that firms weigh the costs a rule would impose on them before deciding whether to grow. 1 is not assumed: the passage says medium firms ''tend to be'' more productive than tiny ones, not that every large firm is more productive than every small one.','केवल 2 पूर्वधारणा है। यह दावा कि सीमा के पास की फ़र्म के पास ''उससे नीचे बने रहने का कारण था'', यह मानकर चलता है कि फ़र्में बढ़ने का निर्णय लेने से पहले उस लागत को तौलती हैं जो कोई नियम उन पर डालेगा। 1 पूर्वधारणा नहीं है: परिच्छेद कहता है कि मध्यम फ़र्में प्रायः बहुत छोटी फ़र्मों से ''अधिक उत्पादक होती हैं'', यह नहीं कि हर बड़ी फ़र्म हर छोटी फ़र्म से अधिक उत्पादक है।','csat-l4-s03-rc-p02-assumptions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Logical Reasoning','Coding-Decoding','mcq','easy','In a certain code, each vowel in a word is replaced by its place among the vowels (A = 1, E = 2, I = 3, O = 4, U = 5), and the consonants are left as they are; MOTHER is written as M4TH2R. How is TEACHER written in that code?','एक विशेष कूट में शब्द के हर स्वर को स्वरों में उसके स्थान (A = 1, E = 2, I = 3, O = 4, U = 5) से बदला जाता है, और व्यंजन जैसे हैं वैसे रहते हैं; MOTHER को M4TH2R लिखा जाता है। उस कूट में TEACHER को कैसे लिखा जाएगा?','{"craft": "inference", "csat_set": "csat-l4-s03", "csat_order": 15}'::jsonb,'[{"id": "a", "body": "T12CH2R", "body_hi": "T12CH2R", "isCorrect": false}, {"id": "b", "body": "T21CH2R", "body_hi": "T21CH2R", "isCorrect": true}, {"id": "c", "body": "T21CH1R", "body_hi": "T21CH1R", "isCorrect": false}, {"id": "d", "body": "T2ACH2R", "body_hi": "T2ACH2R", "isCorrect": false}]'::jsonb,2.5,0.83,'T stays, E becomes 2, A becomes 1, C and H stay, E becomes 2 and R stays: T21CH2R. T12CH2R swaps the two vowels; T21CH1R codes the second E as an A; T2ACH2R leaves the A uncoded.','T वैसा ही रहता है, E बनता है 2, A बनता है 1, C और H वैसे ही रहते हैं, E बनता है 2 और R वैसा ही: T21CH2R। T12CH2R दोनों स्वरों की अदला-बदली कर देता है; T21CH1R दूसरे E को A मानकर लिखता है; T2ACH2R, A को बिना बदले छोड़ देता है।','csat-l4-s03-lr-cd-vowels-written-as-numbers','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','easy','What is 2¹⁰ + 2¹⁰ + 2¹⁰ + 2¹⁰ equal to?','2¹⁰ + 2¹⁰ + 2¹⁰ + 2¹⁰ किसके बराबर है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s03", "csat_order": 16}'::jsonb,'[{"id": "a", "body": "2¹²", "body_hi": "2¹²", "isCorrect": true}, {"id": "b", "body": "2¹⁴", "body_hi": "2¹⁴", "isCorrect": false}, {"id": "c", "body": "2⁴⁰", "body_hi": "2⁴⁰", "isCorrect": false}, {"id": "d", "body": "8¹⁰", "body_hi": "8¹⁰", "isCorrect": false}]'::jsonb,2.5,0.83,'Four equal terms make 4 × 2¹⁰ = 2² × 2¹⁰ = 2¹². 2⁴⁰ multiplies the exponents as though the terms were multiplied together; 8¹⁰ = 2³⁰ and 2¹⁴ have no basis.','चार बराबर पद 4 × 2¹⁰ = 2² × 2¹⁰ = 2¹² बनाते हैं। 2⁴⁰ घातांकों को ऐसे गुणा करता है मानो पदों को आपस में गुणा किया गया हो; 8¹⁰ = 2³⁰ और 2¹⁴ का कोई आधार नहीं।','csat-l4-s03-qa-nt-four-equal-powers-of-2-added','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Permutation & Combination','mcq','hard','In how many ways can six people be split into three pairs (the order of the pairs, and of the two people within a pair, does not matter)?','छह लोगों को तीन जोड़ों में कितने तरीक़ों से बाँटा जा सकता है (जोड़ों का क्रम, और किसी जोड़े के दोनों लोगों का क्रम, मायने नहीं रखता)?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s03", "csat_order": 17}'::jsonb,'[{"id": "a", "body": "15", "body_hi": "15", "isCorrect": true}, {"id": "b", "body": "30", "body_hi": "30", "isCorrect": false}, {"id": "c", "body": "45", "body_hi": "45", "isCorrect": false}, {"id": "d", "body": "90", "body_hi": "90", "isCorrect": false}]'::jsonb,2.5,0.83,'Take any one person: her partner can be chosen in 5 ways. Of the four left, take one: his partner can be chosen in 3 ways. The last two form the third pair. So there are 5 × 3 × 1 = 15 splits. 90 = 6C2 × 4C2 × 2C2 counts the same three pairs in each of their 3! = 6 orders; 45 and 30 remove only part of that over-counting.','किसी एक व्यक्ति को लीजिए: उसका साथी 5 तरीक़ों से चुना जा सकता है। बचे चार में से एक को लीजिए: उसका साथी 3 तरीक़ों से। अंतिम दो तीसरा जोड़ा बनाते हैं। अतः 5 × 3 × 1 = 15 बँटवारे हैं। 90 = 6C2 × 4C2 × 2C2 उन्हीं तीन जोड़ों को उनके 3! = 6 क्रमों में से हर एक में गिनता है; 45 और 30 उस अधिक गिनती का केवल एक भाग हटाते हैं।','csat-l4-s03-qa-pc-six-people-paired-off','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','mcq','easy','''Millions of people take this herbal tonic every day, so it must be good for health.'' Which one of the following best describes the flaw in this argument?','''लाखों लोग रोज़ यह जड़ी-बूटी वाला टॉनिक लेते हैं, इसलिए यह स्वास्थ्य के लिए अच्छा ही होगा।'' निम्नलिखित में से कौन-सा इस तर्क की त्रुटि का सबसे अच्छा वर्णन करता है?','{"craft": "inference", "csat_set": "csat-l4-s03", "csat_order": 18}'::jsonb,'[{"id": "a", "body": "It attacks the people who doubt the tonic instead of answering their doubts.", "body_hi": "यह टॉनिक पर संदेह करने वालों के संदेहों का उत्तर देने के बजाय उन पर हमला करता है।", "isCorrect": false}, {"id": "b", "body": "It assumes that whatever is natural must also be safe for every person.", "body_hi": "यह मान लेता है कि जो कुछ प्राकृतिक है वह हर व्यक्ति के लिए सुरक्षित भी होगा।", "isCorrect": false}, {"id": "c", "body": "It argues in a circle, using its own conclusion as one of its premises.", "body_hi": "यह चक्राकार तर्क करता है, अपने ही निष्कर्ष को अपने आधार-वाक्यों में से एक बनाकर।", "isCorrect": false}, {"id": "d", "body": "It takes the number of people who use the tonic as proof that it works.", "body_hi": "यह टॉनिक लेने वालों की संख्या को उसके असर का प्रमाण मान लेता है।", "isCorrect": true}]'::jsonb,2.5,0.83,'The only reason given is that many people take the tonic, but how many people do something says nothing about whether it works: popular remedies can be useless, and effective ones little used. The argument attacks no doubters, says nothing about the tonic being natural, and does not assume its conclusion.','दिया गया एकमात्र कारण यह है कि बहुत-से लोग टॉनिक लेते हैं, पर कितने लोग कुछ करते हैं, इससे यह पता नहीं चलता कि वह काम करता है: लोकप्रिय उपचार व्यर्थ हो सकते हैं, और प्रभावी उपचार कम प्रयुक्त। तर्क किसी संदेह करने वाले पर हमला नहीं करता, टॉनिक के प्राकृतिक होने के बारे में कुछ नहीं कहता, और अपना निष्कर्ष मान नहीं लेता।','csat-l4-s03-lr-sc-a-remedy-proved-by-its-popularity','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Puzzle Hybrid','mcq','hard','Four people must cross a narrow bridge at night. At most two can cross at a time, and every crossing needs the one torch, which must be carried back for the next pair. Alone they take 1, 2, 5 and 10 minutes to cross; a pair moves at the slower person''s pace. What is the shortest time in which all four can get across?','चार लोगों को रात में एक संकरा पुल पार करना है। एक बार में अधिक से अधिक दो पार कर सकते हैं, और हर बार पार करने के लिए एकमात्र टॉर्च चाहिए, जिसे अगले जोड़े के लिए वापस लाना पड़ता है। अकेले वे पार करने में 1, 2, 5 और 10 मिनट लेते हैं; जोड़ा धीमे व्यक्ति की चाल से चलता है। सभी चारों कम से कम कितने समय में पार कर सकते हैं?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s03", "csat_order": 19}'::jsonb,'[{"id": "a", "body": "15 minutes", "body_hi": "15 मिनट", "isCorrect": false}, {"id": "b", "body": "17 minutes", "body_hi": "17 मिनट", "isCorrect": true}, {"id": "c", "body": "18 minutes", "body_hi": "18 मिनट", "isCorrect": false}, {"id": "d", "body": "19 minutes", "body_hi": "19 मिनट", "isCorrect": false}]'::jsonb,2.5,0.83,'Send the two fastest first (2 minutes), and the 1-minute person brings the torch back (1). Then the two slowest cross together (10), and the 2-minute person brings the torch back (2). Finally the two fastest cross again (2). Total 2 + 1 + 10 + 2 + 2 = 17 minutes. Letting the 1-minute person escort each of the others in turn takes 2 + 1 + 5 + 1 + 10 = 19 minutes: the saving comes from making the 5- and 10-minute people cross together. 15 minutes is not possible; 18 minutes has no basis.','पहले दो सबसे तेज़ लोगों को भेजिए (2 मिनट), और 1 मिनट वाला टॉर्च वापस लाता है (1)। फिर दो सबसे धीमे साथ पार करते हैं (10), और 2 मिनट वाला टॉर्च वापस लाता है (2)। अंत में दो सबसे तेज़ फिर पार करते हैं (2)। कुल 2 + 1 + 10 + 2 + 2 = 17 मिनट। 1 मिनट वाले को बारी-बारी से बाक़ी सबके साथ भेजने में 2 + 1 + 5 + 1 + 10 = 19 मिनट लगते हैं: बचत 5 और 10 मिनट वालों को साथ पार कराने से आती है। 15 मिनट संभव नहीं; 18 मिनट का कोई आधार नहीं।','csat-l4-s03-qa-ph-four-people-and-one-torch','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Best Summary','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Many forests are shaped by fire, and some depend on it. Where small fires once burned through the undergrowth every few years, the habit of putting out every fire at once lets dead leaves and branches pile up, so that when a fire finally escapes control it burns far hotter and wider. Land managers in several countries have therefore revived the practice of deliberately setting small, cool fires in the right season, as some Indigenous communities long did, to clear away fuel before it builds up. The lesson is not that fire is always good for forests. Planned burns can escape, their smoke harms people''s lungs, and wet tropical forests that rarely burn are badly damaged by it. Fire is a tool to be used where an ecosystem has grown up with it, not a general cure.

Which one of the following statements best reflects the most logical and rational message conveyed by the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
कई वन आग से आकार लेते हैं, और कुछ उस पर निर्भर भी हैं। जहाँ कभी हर कुछ वर्षों में छोटी आगें झाड़ियों में से गुज़र जाती थीं, वहाँ हर आग को तुरंत बुझा देने की आदत सूखी पत्तियों और टहनियों को जमा होने देती है, जिससे जब अंततः कोई आग नियंत्रण से बाहर निकलती है तो वह कहीं अधिक गर्म और व्यापक जलती है। इसलिए कई देशों में भूमि-प्रबंधकों ने सही मौसम में जान-बूझकर छोटी, कम तापमान वाली आगें लगाने की प्रथा फिर से शुरू की है, जैसा कुछ मूल निवासी समुदाय लंबे समय से करते थे, ताकि ईंधन जमा होने से पहले हट जाए। सीख यह नहीं कि आग हमेशा वनों के लिए अच्छी है। नियोजित आगें बेक़ाबू हो सकती हैं, उनका धुआँ लोगों के फेफड़ों को हानि पहुँचाता है, और नम उष्णकटिबंधीय वन, जो विरले ही जलते हैं, उससे बुरी तरह क्षतिग्रस्त होते हैं। आग उन जगहों के लिए उपकरण है जहाँ कोई पारितंत्र उसके साथ विकसित हुआ है, सामान्य उपचार नहीं।

निम्नलिखित में से कौन-सा कथन परिच्छेद द्वारा दिए गए सबसे तार्किक और विवेकपूर्ण संदेश को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s03", "passage_group": "csat-l4-s03-p03", "csat_order": 20}'::jsonb,'[{"id": "a", "body": "Every forest fire should be put out at once, however small it is, to protect the trees.", "body_hi": "पेड़ों की रक्षा के लिए वन की हर आग तुरंत बुझाई जाए, वह चाहे कितनी भी छोटी हो।", "isCorrect": false}, {"id": "b", "body": "Forests should be left to burn freely, since fire is natural and always good for them.", "body_hi": "वनों को खुलकर जलने दिया जाए, क्योंकि आग प्राकृतिक है और उनके लिए हमेशा अच्छी है।", "isCorrect": false}, {"id": "c", "body": "Wet tropical forests benefit most from deliberate burning, since they burn so rarely.", "body_hi": "नम उष्णकटिबंधीय वनों को जान-बूझकर जलाने से सबसे अधिक लाभ होता है, क्योंकि वे विरले जलते हैं।", "isCorrect": false}, {"id": "d", "body": "Planned burning can prevent worse fires where forests have grown up with fire.", "body_hi": "जहाँ वन आग के साथ विकसित हुए हैं, वहाँ नियोजित आग बदतर आगों को रोक सकती है।", "isCorrect": true}]'::jsonb,2.5,0.83,'The passage argues that putting out every fire can make later fires worse, so planned small burns help where forests have grown up with fire -- but that fire is not good for every forest. It does not say every fire should be put out at once, which it says makes fires worse; nor that forests should be left to burn freely, since it recommends small, planned fires; nor that tropical forests benefit, which it says are badly damaged.','परिच्छेद तर्क देता है कि हर आग बुझा देने से बाद की आगें और बुरी हो सकती हैं, इसलिए जहाँ वन आग के साथ विकसित हुए हैं वहाँ नियोजित छोटी आगें सहायक हैं -- पर आग हर वन के लिए अच्छी नहीं। वह यह नहीं कहता कि हर आग तुरंत बुझाई जाए, जिससे उसके अनुसार आगें और बुरी होती हैं; न यह कि वनों को खुलकर जलने दिया जाए, क्योंकि वह छोटी, नियोजित आगों की सलाह देता है; न यह कि उष्णकटिबंधीय वनों को लाभ होता है, जिन्हें वह बुरी तरह क्षतिग्रस्त बताता है।','csat-l4-s03-rc-p03-message','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Many forests are shaped by fire, and some depend on it. Where small fires once burned through the undergrowth every few years, the habit of putting out every fire at once lets dead leaves and branches pile up, so that when a fire finally escapes control it burns far hotter and wider. Land managers in several countries have therefore revived the practice of deliberately setting small, cool fires in the right season, as some Indigenous communities long did, to clear away fuel before it builds up. The lesson is not that fire is always good for forests. Planned burns can escape, their smoke harms people''s lungs, and wet tropical forests that rarely burn are badly damaged by it. Fire is a tool to be used where an ecosystem has grown up with it, not a general cure.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
कई वन आग से आकार लेते हैं, और कुछ उस पर निर्भर भी हैं। जहाँ कभी हर कुछ वर्षों में छोटी आगें झाड़ियों में से गुज़र जाती थीं, वहाँ हर आग को तुरंत बुझा देने की आदत सूखी पत्तियों और टहनियों को जमा होने देती है, जिससे जब अंततः कोई आग नियंत्रण से बाहर निकलती है तो वह कहीं अधिक गर्म और व्यापक जलती है। इसलिए कई देशों में भूमि-प्रबंधकों ने सही मौसम में जान-बूझकर छोटी, कम तापमान वाली आगें लगाने की प्रथा फिर से शुरू की है, जैसा कुछ मूल निवासी समुदाय लंबे समय से करते थे, ताकि ईंधन जमा होने से पहले हट जाए। सीख यह नहीं कि आग हमेशा वनों के लिए अच्छी है। नियोजित आगें बेक़ाबू हो सकती हैं, उनका धुआँ लोगों के फेफड़ों को हानि पहुँचाता है, और नम उष्णकटिबंधीय वन, जो विरले ही जलते हैं, उससे बुरी तरह क्षतिग्रस्त होते हैं। आग उन जगहों के लिए उपकरण है जहाँ कोई पारितंत्र उसके साथ विकसित हुआ है, सामान्य उपचार नहीं।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["A forest in which every small fire has been put out for many decades may face a more severe fire than one in which small fires were allowed.", "Planned burning would protect wet tropical forests just as it protects forests that have grown up with fire."], "statements_hi": ["जिस वन में दशकों से हर छोटी आग बुझाई गई है, उसमें ऐसी आग का सामना हो सकता है जो उस वन से अधिक गंभीर हो जिसमें छोटी आगें होने दी गईं।", "नियोजित आग नम उष्णकटिबंधीय वनों की रक्षा भी वैसे ही करेगी जैसे वह आग के साथ विकसित हुए वनों की करती है।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s03", "passage_group": "csat-l4-s03-p03", "csat_order": 21}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 1 is valid. The passage says that putting out every fire lets fuel pile up so that an escaped fire ''burns far hotter and wider''; so a forest where small fires have long been prevented is at greater risk of a severe fire. 2 contradicts it: wet tropical forests ''that rarely burn are badly damaged'' by fire, so planned burning there would not help in the same way.','केवल 1 वैध है। परिच्छेद कहता है कि हर आग बुझा देने से ईंधन जमा होता है जिससे बेक़ाबू आग ''कहीं अधिक गर्म और व्यापक जलती है''; इसलिए जिस वन में लंबे समय से छोटी आगें रोकी गई हैं, उसमें गंभीर आग का जोखिम अधिक है। 2 उसका खंडन करता है: ''जो विरले ही जलते हैं'' वे नम उष्णकटिबंधीय वन आग से ''बुरी तरह क्षतिग्रस्त होते हैं'', इसलिए वहाँ नियोजित आग उसी तरह सहायक नहीं होगी।','csat-l4-s03-rc-p03-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Sequences & Series','mcq','medium','What is the sum 1 + 11 + 111 + 1,111 + 11,111 + 1,11,111?','योग 1 + 11 + 111 + 1,111 + 11,111 + 1,11,111 क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s03", "csat_order": 22}'::jsonb,'[{"id": "a", "body": "1,11,111", "body_hi": "1,11,111", "isCorrect": false}, {"id": "b", "body": "1,21,212", "body_hi": "1,21,212", "isCorrect": false}, {"id": "c", "body": "1,23,321", "body_hi": "1,23,321", "isCorrect": false}, {"id": "d", "body": "1,23,456", "body_hi": "1,23,456", "isCorrect": true}]'::jsonb,2.5,0.83,'Add column by column from the right: the units column has six 1s, the tens five, the hundreds four, and so on down to one in the lakhs place. No column reaches 10, so there are no carries, and the sum reads 1, 2, 3, 4, 5, 6 from the left: 1,23,456. 1,11,111 is just the last term; 1,23,321 and 1,21,212 misplace the column totals.','दाईं ओर से स्तंभ-दर-स्तंभ जोड़िए: इकाई के स्तंभ में छह 1 हैं, दहाई में पाँच, सैकड़े में चार, और इसी तरह लाख के स्थान पर एक। कोई स्तंभ 10 तक नहीं पहुँचता, इसलिए कोई हासिल नहीं, और योग बाएँ से 1, 2, 3, 4, 5, 6 पढ़ा जाता है: 1,23,456। 1,11,111 केवल अंतिम पद है; 1,23,321 और 1,21,212 स्तंभों के योग ग़लत जगह रखते हैं।','csat-l4-s03-qa-ss-a-sum-of-repunits','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Seating Arrangement','mcq','medium','Four men, A, B, C and D, are married to four women, P, Q, R and S, one each. A is married to none of P, Q and S. Q is married to B or to C. S is not married to C or to D. B is not married to P. To whom is C married?','चार पुरुष, A, B, C और D, चार महिलाओं, P, Q, R और S, से विवाहित हैं, हर एक एक से। A का विवाह P, Q और S में से किसी से नहीं हुआ है। Q का विवाह B या C से हुआ है। S का विवाह न C से हुआ है न D से। B का विवाह P से नहीं हुआ है। C का विवाह किससे हुआ है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s03", "csat_order": 23}'::jsonb,'[{"id": "a", "body": "P", "body_hi": "P", "isCorrect": false}, {"id": "b", "body": "Q", "body_hi": "Q", "isCorrect": true}, {"id": "c", "body": "R", "body_hi": "R", "isCorrect": false}, {"id": "d", "body": "S", "body_hi": "S", "isCorrect": false}]'::jsonb,2.5,0.83,'A is married to none of P, Q and S, so A is married to R. S is not married to C or D, and not to A, so S is married to B. Q is married to B or C; B is taken, so Q is married to C. That leaves D married to P, which fits the clue that B is not married to P. So C is married to Q.','A का विवाह P, Q और S में से किसी से नहीं हुआ, इसलिए A का विवाह R से हुआ है। S का विवाह न C से हुआ है न D से, और A से भी नहीं, इसलिए S का विवाह B से हुआ है। Q का विवाह B या C से हुआ है; B का विवाह हो चुका, इसलिए Q का विवाह C से हुआ है। इससे D का विवाह P से बचता है, जो इस संकेत से मेल खाता है कि B का विवाह P से नहीं हुआ। अतः C का विवाह Q से हुआ है।','csat-l4-s03-lr-sa-four-couples','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','hard','Three different prime numbers add up to 100, and one of them is 36 more than another. What is the largest of the three?','तीन अलग-अलग अभाज्य संख्याओं का योग 100 है, और उनमें से एक दूसरी से 36 अधिक है। तीनों में सबसे बड़ी क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s03", "csat_order": 24}'::jsonb,'[{"id": "a", "body": "31", "body_hi": "31", "isCorrect": false}, {"id": "b", "body": "59", "body_hi": "59", "isCorrect": false}, {"id": "c", "body": "67", "body_hi": "67", "isCorrect": true}, {"id": "d", "body": "71", "body_hi": "71", "isCorrect": false}]'::jsonb,2.5,0.83,'Three odd primes would add up to an odd number, so one of the three must be 2, the only even prime. The other two add up to 98. If they differ by 36 they are 67 and 31, both prime. (The difference cannot involve 2, since 38 is not prime.) So the primes are 2, 31 and 67, and the largest is 67. 31 is the smaller of the pair; 59 and 71 do not fit with 2 and a partner to make 100 with a difference of 36.','तीन विषम अभाज्य संख्याओं का योग विषम होता, इसलिए तीनों में से एक 2 होनी चाहिए, एकमात्र सम अभाज्य। बाक़ी दो का योग 98 है। यदि उनमें 36 का अंतर है तो वे 67 और 31 हैं, दोनों अभाज्य। (अंतर में 2 शामिल नहीं हो सकती, क्योंकि 38 अभाज्य नहीं।) अतः अभाज्य संख्याएँ 2, 31 और 67 हैं, और सबसे बड़ी 67 है। 31 जोड़े की छोटी संख्या है; 59 और 71, 2 और किसी साथी के साथ 36 के अंतर से 100 नहीं बनातीं।','csat-l4-s03-qa-nt-three-primes-that-add-to-100','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Speed-Distance-Time','mcq','easy','A runner''s pace is 5 minutes per kilometre. What is her speed?','एक धावक की गति प्रति किलोमीटर 5 मिनट है। उसकी चाल क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s03", "csat_order": 25}'::jsonb,'[{"id": "a", "body": "12 km/h", "body_hi": "12 किमी/घंटा", "isCorrect": true}, {"id": "b", "body": "15 km/h", "body_hi": "15 किमी/घंटा", "isCorrect": false}, {"id": "c", "body": "20 km/h", "body_hi": "20 किमी/घंटा", "isCorrect": false}, {"id": "d", "body": "30 km/h", "body_hi": "30 किमी/घंटा", "isCorrect": false}]'::jsonb,2.5,0.83,'At 5 minutes for each kilometre she covers 60 ÷ 5 = 12 km in an hour: 12 km/h. 15 km/h would be 4 minutes a kilometre, 20 km/h 3 minutes and 30 km/h 2 minutes.','हर किलोमीटर में 5 मिनट से वह एक घंटे में 60 ÷ 5 = 12 किमी चलती है: 12 किमी/घंटा। 15 किमी/घंटा का अर्थ प्रति किलोमीटर 4 मिनट, 20 किमी/घंटा का 3 मिनट और 30 किमी/घंटा का 2 मिनट होगा।','csat-l4-s03-qa-sdt-a-runner-s-pace','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Syllogism','statement_based','hard','Statements: More than half of the members of a club are teachers. More than half of the members of the club are singers.

Which of the following conclusions follow(s) from the statements?','कथन: एक क्लब के आधे से अधिक सदस्य शिक्षक हैं। उसी क्लब के आधे से अधिक सदस्य गायक हैं।

निम्नलिखित में से कौन-सा/से निष्कर्ष कथनों से निकलता/निकलते है/हैं?','{"statements": ["Some members of the club are both teachers and singers.", "Every member of the club is either a teacher or a singer."], "statements_hi": ["क्लब के कुछ सदस्य शिक्षक और गायक दोनों हैं।", "क्लब का हर सदस्य या तो शिक्षक है या गायक।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "numbering": "roman", "csat_set": "csat-l4-s03", "csat_order": 26}'::jsonb,'[{"id": "a", "body": "I only", "body_hi": "केवल I", "isCorrect": true}, {"id": "b", "body": "II only", "body_hi": "केवल II", "isCorrect": false}, {"id": "c", "body": "Both I and II", "body_hi": "I और II दोनों", "isCorrect": false}, {"id": "d", "body": "Neither I nor II", "body_hi": "न तो I, न ही II", "isCorrect": false}]'::jsonb,2.5,0.83,'Only I follows. If no member were both, the teachers and the singers would be separate groups, together more than the whole club -- impossible; so some members are both. II does not follow: with ten members, six teachers and six singers can overlap in four, leaving two members who are neither.','केवल I निकलता है। यदि कोई सदस्य दोनों न होता, तो शिक्षक और गायक अलग-अलग समूह होते, जो मिलकर पूरे क्लब से अधिक होते -- असंभव; इसलिए कुछ सदस्य दोनों हैं। II नहीं निकलता: दस सदस्यों में छह शिक्षक और छह गायक चार में साझा हो सकते हैं, जिससे दो सदस्य ऐसे बचते हैं जो दोनों में से कुछ नहीं।','csat-l4-s03-lr-sy-more-than-half-twice','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Meat can now be grown from animal cells in steel tanks, without raising and slaughtering animals. Singapore approved such meat for sale in 2020 and the United States in 2023. Its supporters point to the land, water and suffering it could spare. The climate case is less certain than it sounds. The tanks must be kept sterile and warm and fed with purified nutrients, all of which take a great deal of energy; some studies suggest that if that energy comes from fossil fuels, cell-grown meat could cause more emissions than some kinds of farmed meat. Its environmental promise therefore depends heavily on clean power and on cheaper ways of feeding the cells -- conditions that do not yet exist at scale.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
अब मांस को जानवरों को पालने और मारने के बिना, स्टील की टंकियों में जानवरों की कोशिकाओं से उगाया जा सकता है। सिंगापुर ने ऐसे मांस को 2020 में बिक्री की स्वीकृति दी और संयुक्त राज्य अमेरिका ने 2023 में। इसके समर्थक उस भूमि, पानी और पीड़ा की ओर संकेत करते हैं जो इससे बच सकती है। जलवायु का तर्क उतना निश्चित नहीं जितना लगता है। टंकियों को रोगाणु-रहित और गर्म रखना और उन्हें शुद्ध पोषक तत्व देना पड़ता है, और इन सबमें बहुत ऊर्जा लगती है; कुछ अध्ययन संकेत देते हैं कि यदि वह ऊर्जा जीवाश्म ईंधनों से आए, तो कोशिकाओं से उगाया मांस कुछ प्रकार के पाले गए मांस से अधिक उत्सर्जन कर सकता है। इसलिए उसका पर्यावरणीय वादा बहुत हद तक स्वच्छ बिजली और कोशिकाओं को पोषण देने के सस्ते तरीक़ों पर निर्भर है -- ऐसी परिस्थितियाँ जो अभी बड़े पैमाने पर मौजूद नहीं हैं।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s03", "passage_group": "csat-l4-s03-p04", "csat_order": 27}'::jsonb,'[{"id": "a", "body": "Meat grown from cells is certain to cut greenhouse emissions wherever it replaces farmed meat.", "body_hi": "कोशिकाओं से उगाया मांस जहाँ भी पाले गए मांस की जगह लेगा, वहाँ ग्रीनहाउस उत्सर्जन निश्चित रूप से घटाएगा।", "isCorrect": false}, {"id": "b", "body": "Meat grown from cells is worse for the climate than farmed meat in every possible case.", "body_hi": "कोशिकाओं से उगाया मांस हर संभव स्थिति में पाले गए मांस से जलवायु के लिए बुरा है।", "isCorrect": false}, {"id": "c", "body": "Cell-grown meat spares animals and land, but its climate benefit depends on clean energy.", "body_hi": "कोशिकाओं से उगाया मांस जानवर और भूमि बचाता है, पर उसका जलवायु लाभ स्वच्छ ऊर्जा पर निर्भर है।", "isCorrect": true}, {"id": "d", "body": "Meat grown from cells should be banned until it can be shown to be as cheap as farmed meat.", "body_hi": "कोशिकाओं से उगाए मांस पर तब तक प्रतिबंध रहे जब तक यह न दिखाया जा सके कि वह पाले गए मांस जितना सस्ता है।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage grants the benefits of cell-grown meat in land, water and suffering, but says its climate benefit depends on clean power and cheaper feeding, which do not yet exist at scale. It does not say the meat is certain to cut emissions, or that it is worse for the climate in every case -- only that it could be if powered by fossil fuels; and it does not call for a ban.','परिच्छेद भूमि, पानी और पीड़ा में कोशिकाओं से उगाए मांस के लाभ मानता है, पर कहता है कि उसका जलवायु लाभ स्वच्छ बिजली और सस्ते पोषण पर निर्भर है, जो अभी बड़े पैमाने पर मौजूद नहीं। वह यह नहीं कहता कि यह मांस निश्चित रूप से उत्सर्जन घटाएगा, या हर स्थिति में जलवायु के लिए बुरा है -- केवल यह कि जीवाश्म ईंधनों से चलने पर ऐसा हो सकता है; और वह प्रतिबंध की माँग नहीं करता।','csat-l4-s03-rc-p04-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Specific Detail','mcq','easy','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Meat can now be grown from animal cells in steel tanks, without raising and slaughtering animals. Singapore approved such meat for sale in 2020 and the United States in 2023. Its supporters point to the land, water and suffering it could spare. The climate case is less certain than it sounds. The tanks must be kept sterile and warm and fed with purified nutrients, all of which take a great deal of energy; some studies suggest that if that energy comes from fossil fuels, cell-grown meat could cause more emissions than some kinds of farmed meat. Its environmental promise therefore depends heavily on clean power and on cheaper ways of feeding the cells -- conditions that do not yet exist at scale.

According to the passage, why does growing meat from cells take so much energy?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
अब मांस को जानवरों को पालने और मारने के बिना, स्टील की टंकियों में जानवरों की कोशिकाओं से उगाया जा सकता है। सिंगापुर ने ऐसे मांस को 2020 में बिक्री की स्वीकृति दी और संयुक्त राज्य अमेरिका ने 2023 में। इसके समर्थक उस भूमि, पानी और पीड़ा की ओर संकेत करते हैं जो इससे बच सकती है। जलवायु का तर्क उतना निश्चित नहीं जितना लगता है। टंकियों को रोगाणु-रहित और गर्म रखना और उन्हें शुद्ध पोषक तत्व देना पड़ता है, और इन सबमें बहुत ऊर्जा लगती है; कुछ अध्ययन संकेत देते हैं कि यदि वह ऊर्जा जीवाश्म ईंधनों से आए, तो कोशिकाओं से उगाया मांस कुछ प्रकार के पाले गए मांस से अधिक उत्सर्जन कर सकता है। इसलिए उसका पर्यावरणीय वादा बहुत हद तक स्वच्छ बिजली और कोशिकाओं को पोषण देने के सस्ते तरीक़ों पर निर्भर है -- ऐसी परिस्थितियाँ जो अभी बड़े पैमाने पर मौजूद नहीं हैं।

परिच्छेद के अनुसार, कोशिकाओं से मांस उगाने में इतनी ऊर्जा क्यों लगती है?','{"craft": "precision", "csat_set": "csat-l4-s03", "passage_group": "csat-l4-s03-p04", "csat_order": 28}'::jsonb,'[{"id": "a", "body": "The tanks must be kept sterile and warm, and fed with purified nutrients", "body_hi": "टंकियों को रोगाणु-रहित और गर्म रखना और उन्हें शुद्ध पोषक तत्व देना पड़ता है", "isCorrect": true}, {"id": "b", "body": "The finished meat must be frozen at once and kept frozen until it is sold", "body_hi": "तैयार मांस को तुरंत जमाना और बिकने तक जमाए रखना पड़ता है", "isCorrect": false}, {"id": "c", "body": "The meat has to be flown to distant markets soon after it has been made", "body_hi": "मांस बनने के तुरंत बाद उसे हवाई जहाज़ से दूर के बाज़ारों तक ले जाना पड़ता है", "isCorrect": false}, {"id": "d", "body": "The cells need bright light, day and night, in order to grow at all", "body_hi": "कोशिकाओं को बढ़ने के लिए दिन-रात तेज़ रोशनी की आवश्यकता होती है", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage says the tanks ''must be kept sterile and warm and fed with purified nutrients, all of which take a great deal of energy''. It says nothing about cooling the meat, transporting it by air, or lighting the tanks.','परिच्छेद कहता है कि टंकियों को ''रोगाणु-रहित और गर्म रखना और उन्हें शुद्ध पोषक तत्व देना पड़ता है, और इन सबमें बहुत ऊर्जा लगती है''। वह मांस को ठंडा करने, हवाई जहाज़ से ले जाने या टंकियों में रोशनी करने के बारे में कुछ नहीं कहता।','csat-l4-s03-rc-p04-why-it-takes-energy','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','hard','The numbers 1, 2, 3, ..., 10 are written on a board. At each step any two numbers on the board are rubbed out and replaced by their difference (the larger minus the smaller). This is repeated until only one number is left. What can be said about that number?','बोर्ड पर संख्याएँ 1, 2, 3, ..., 10 लिखी हैं। हर चरण में बोर्ड की कोई दो संख्याएँ मिटाकर उनकी जगह उनका अंतर (बड़ी में से छोटी) लिखा जाता है। यह तब तक दोहराया जाता है जब तक केवल एक संख्या न बचे। उस संख्या के बारे में क्या कहा जा सकता है?','{"craft": "inference", "csat_set": "csat-l4-s03", "csat_order": 29}'::jsonb,'[{"id": "a", "body": "It is always even.", "body_hi": "वह हमेशा सम होती है।", "isCorrect": false}, {"id": "b", "body": "It is always 1.", "body_hi": "वह हमेशा 1 होती है।", "isCorrect": false}, {"id": "c", "body": "It may be any whole number from 0 to 10.", "body_hi": "वह 0 से 10 तक कोई भी पूर्ण संख्या हो सकती है।", "isCorrect": false}, {"id": "d", "body": "It is always odd.", "body_hi": "वह हमेशा विषम होती है।", "isCorrect": true}]'::jsonb,2.5,0.83,'Replacing x and y by x - y changes the sum of all the numbers by 2y, an even amount, so the sum never changes from odd to even or back. It starts at 1 + 2 + ... + 10 = 55, which is odd, so the last number -- which is the whole sum at the end -- is odd. It need not be 1: different orders of rubbing out can leave 1, 3, 5, 7 or 9. It can never be even, and so it cannot be any number from 0 to 10.','x और y की जगह x - y लिखने से सभी संख्याओं का योग 2y, एक सम राशि, से बदलता है, इसलिए योग कभी विषम से सम या उलटा नहीं होता। वह 1 + 2 + ... + 10 = 55 से शुरू होता है, जो विषम है, इसलिए अंतिम संख्या -- जो अंत में पूरा योग है -- विषम है। उसका 1 होना आवश्यक नहीं: मिटाने के अलग-अलग क्रमों से 1, 3, 5, 7 या 9 बच सकती है। वह कभी सम नहीं हो सकती, इसलिए 0 से 10 तक कोई भी संख्या नहीं हो सकती।','csat-l4-s03-qa-nt-a-number-left-on-a-board-after-differences','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Geometry & Mensuration','mcq','medium','A cylindrical water tank has an inner radius of 3.5 m and a depth of 4 m. How many litres of water does it hold when full? (Take π = 22/7.)','एक बेलनाकार पानी की टंकी की भीतरी त्रिज्या 3.5 मीटर और गहराई 4 मीटर है। भरी होने पर उसमें कितने लीटर पानी आता है? (π = 22/7 लीजिए।)','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s03", "csat_order": 30}'::jsonb,'[{"id": "a", "body": "15,400 litres", "body_hi": "15,400 लीटर", "isCorrect": false}, {"id": "b", "body": "1,54,000 litres", "body_hi": "1,54,000 लीटर", "isCorrect": true}, {"id": "c", "body": "15,40,000 litres", "body_hi": "15,40,000 लीटर", "isCorrect": false}, {"id": "d", "body": "1,54,00,000 litres", "body_hi": "1,54,00,000 लीटर", "isCorrect": false}]'::jsonb,2.5,0.83,'The volume is πr²h = 22/7 × 3.5 × 3.5 × 4 = 154 m³. One cubic metre holds 1,000 litres, so the tank holds 154 × 1,000 = 1,54,000 litres. 15,400 litres takes a cubic metre as 100 litres; 15,40,000 litres takes it as 10,000; 1,54,00,000 litres multiplies by 1,00,000.','आयतन πr²h = 22/7 × 3.5 × 3.5 × 4 = 154 घन मीटर है। एक घन मीटर में 1,000 लीटर आते हैं, इसलिए टंकी में 154 × 1,000 = 1,54,000 लीटर आता है। 15,400 लीटर एक घन मीटर को 100 लीटर मानता है; 15,40,000 लीटर उसे 10,000 मानता है; 1,54,00,000 लीटर 1,00,000 से गुणा करता है।','csat-l4-s03-qa-gm-the-litres-in-a-cylindrical-tank','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Coding-Decoding','mcq','medium','In a certain code, each letter of a word is replaced by the product of its place in the word and its place in the alphabet; ABC is written as 1-4-9. How is CAB written in that code?','एक विशेष कूट में शब्द के हर अक्षर को शब्द में उसके स्थान और वर्णमाला में उसके स्थान के गुणनफल से बदला जाता है; ABC को 1-4-9 लिखा जाता है। उस कूट में CAB को कैसे लिखा जाएगा?','{"craft": "inference", "csat_set": "csat-l4-s03", "csat_order": 31}'::jsonb,'[{"id": "a", "body": "1-4-9", "body_hi": "1-4-9", "isCorrect": false}, {"id": "b", "body": "3-1-2", "body_hi": "3-1-2", "isCorrect": false}, {"id": "c", "body": "9-2-3", "body_hi": "9-2-3", "isCorrect": false}, {"id": "d", "body": "3-2-6", "body_hi": "3-2-6", "isCorrect": true}]'::jsonb,2.5,0.83,'C is 3rd in the alphabet and 1st in the word: 3 × 1 = 3. A is 1st in the alphabet and 2nd in the word: 1 × 2 = 2. B is 2nd and 3rd: 2 × 3 = 6. So CAB is 3-2-6. 1-4-9 is the code of ABC, unchanged; 3-1-2 gives only the alphabet places; 9-2-3 multiplies C by its alphabet place twice.','C वर्णमाला में तीसरा और शब्द में पहला है: 3 × 1 = 3। A वर्णमाला में पहला और शब्द में दूसरा है: 1 × 2 = 2। B दूसरा और तीसरा है: 2 × 3 = 6। अतः CAB = 3-2-6। 1-4-9, ABC का कूट है, बिना बदले; 3-1-2 केवल वर्णमाला के स्थान देता है; 9-2-3, C को उसके वर्णमाला स्थान से दो बार गुणा करता है।','csat-l4-s03-lr-cd-letters-times-their-places','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Percentage & Profit-Loss','mcq','hard','A trader buys goods for ₹1,000 plus 18 per cent GST and sells them for ₹1,500 plus 18 per cent GST. Under the GST rule that tax paid on purchases can be set off against tax collected on sales, how much GST must the trader pay to the government on this deal?','एक व्यापारी ₹1,000 और उस पर 18 प्रतिशत जीएसटी देकर माल ख़रीदता है और उसे ₹1,500 और उस पर 18 प्रतिशत जीएसटी लेकर बेचता है। जीएसटी के इस नियम के अंतर्गत कि ख़रीद पर चुकाया कर बिक्री पर वसूले कर में समायोजित किया जा सकता है, इस सौदे पर व्यापारी को सरकार को कितना जीएसटी देना होगा?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s03", "csat_order": 32}'::jsonb,'[{"id": "a", "body": "₹90", "body_hi": "₹90", "isCorrect": true}, {"id": "b", "body": "₹180", "body_hi": "₹180", "isCorrect": false}, {"id": "c", "body": "₹270", "body_hi": "₹270", "isCorrect": false}, {"id": "d", "body": "₹450", "body_hi": "₹450", "isCorrect": false}]'::jsonb,2.5,0.83,'The trader collects 18 per cent of ₹1,500 = ₹270 from the buyer, but has already paid 18 per cent of ₹1,000 = ₹180 to the seller. Setting the tax paid off against the tax collected leaves 270 - 180 = ₹90 -- which is 18 per cent of the ₹500 of value the trader added. ₹270 forgets the set-off; ₹180 is the tax paid on the purchase; ₹450 adds the two.','व्यापारी ख़रीदार से ₹1,500 का 18 प्रतिशत = ₹270 वसूलता है, पर विक्रेता को पहले ही ₹1,000 का 18 प्रतिशत = ₹180 चुका चुका है। चुकाए गए कर को वसूले गए कर में समायोजित करने पर 270 - 180 = ₹90 बचते हैं -- जो व्यापारी द्वारा जोड़े गए ₹500 के मूल्य का 18 प्रतिशत है। ₹270 समायोजन भूल जाता है; ₹180 ख़रीद पर चुकाया कर है; ₹450 दोनों को जोड़ देता है।','csat-l4-s03-qa-pp-the-gst-a-trader-pays-over','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Speed-Distance-Time','mcq','medium','A car takes 4 hours to cover a distance that a train covers in 3 hours. The train is 20 km/h faster than the car. How long is the distance?','एक गाड़ी किसी दूरी को 4 घंटे में तय करती है जिसे एक रेलगाड़ी 3 घंटे में तय करती है। रेलगाड़ी गाड़ी से 20 किमी/घंटा तेज़ है। दूरी कितनी है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s03", "csat_order": 33}'::jsonb,'[{"id": "a", "body": "60 km", "body_hi": "60 किमी", "isCorrect": false}, {"id": "b", "body": "180 km", "body_hi": "180 किमी", "isCorrect": false}, {"id": "c", "body": "200 km", "body_hi": "200 किमी", "isCorrect": false}, {"id": "d", "body": "240 km", "body_hi": "240 किमी", "isCorrect": true}]'::jsonb,2.5,0.83,'If the car''s speed is v, then 4v = 3(v + 20), so v = 60 km/h and the train''s speed is 80 km/h. The distance is 4 × 60 = 3 × 80 = 240 km. 60 km is the car''s speed, not the distance; 180 km multiplies the car''s speed by the train''s time; 200 km has no basis.','यदि गाड़ी की चाल v है, तो 4v = 3(v + 20), इसलिए v = 60 किमी/घंटा और रेलगाड़ी की चाल 80 किमी/घंटा। दूरी 4 × 60 = 3 × 80 = 240 किमी है। 60 किमी गाड़ी की चाल है, दूरी नहीं; 180 किमी गाड़ी की चाल को रेलगाड़ी के समय से गुणा करता है; 200 किमी का कोई आधार नहीं।','csat-l4-s03-qa-sdt-a-car-and-a-train-on-the-same-distance','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In the five years of his rule, from 1540 to 1545, Sher Shah Suri rebuilt and extended the great road that ran from Bengal across the plains to the north-west. Along it he set up sarais, rest houses for travellers at regular stages, dug wells and planted shade trees; the sarais also served as stations for a mounted postal service that carried news and orders quickly across the kingdom. He is remembered too for issuing a silver coin, the rupiya, whose name survives in the rupee. It is easy to credit the road to one ruler. In fact a highway along much the same route already linked the cities of the plains in Mauryan times, and the Mughals and later the British, who named it the Grand Trunk Road, kept rebuilding it. What Sher Shah added was a system of upkeep and services that made the road work as an instrument of government.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1540 से 1545 तक के अपने पाँच वर्षों के शासन में शेरशाह सूरी ने उस महान सड़क का पुनर्निर्माण और विस्तार किया जो बंगाल से मैदानों को पार करती हुई उत्तर-पश्चिम तक जाती थी। उसके किनारे उन्होंने सरायें बनवाईं, यात्रियों के लिए नियमित पड़ावों पर विश्राम-गृह, कुएँ खुदवाए और छायादार पेड़ लगवाए; सरायें घुड़सवार डाक-सेवा के ठिकानों का भी काम करती थीं, जो समाचार और आदेश राज्य भर में तेज़ी से पहुँचाती थी। उन्हें चाँदी का एक सिक्का, रुपया, जारी करने के लिए भी याद किया जाता है, जिसका नाम ''रुपये'' में आज भी जीवित है। सड़क का श्रेय एक शासक को दे देना आसान है। वास्तव में लगभग इसी मार्ग पर एक राजमार्ग मौर्य काल में ही मैदानों के नगरों को जोड़ता था, और मुग़ल और बाद में अंग्रेज़, जिन्होंने उसे ग्रैंड ट्रंक रोड नाम दिया, उसका पुनर्निर्माण करते रहे। शेरशाह ने जो जोड़ा वह रख-रखाव और सेवाओं की एक व्यवस्था थी जिसने सड़क को शासन के एक साधन के रूप में काम करने योग्य बनाया।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s03", "passage_group": "csat-l4-s03-p05", "csat_order": 34}'::jsonb,'[{"id": "a", "body": "Sher Shah built the first road ever to cross the northern plains from Bengal to the north-west.", "body_hi": "शेरशाह ने बंगाल से उत्तर-पश्चिम तक उत्तरी मैदानों को पार करने वाली पहली सड़क बनाई।", "isCorrect": false}, {"id": "b", "body": "The British were the first to build a road along the route that they named the Grand Trunk Road.", "body_hi": "अंग्रेज़ों ने ही सबसे पहले उस मार्ग पर सड़क बनाई जिसे उन्होंने ग्रैंड ट्रंक रोड नाम दिया।", "isCorrect": false}, {"id": "c", "body": "Sher Shah''s most lasting achievement was the silver coin from which the rupee takes its name.", "body_hi": "शेरशाह की सबसे स्थायी उपलब्धि चाँदी का वह सिक्का था जिससे रुपये को उसका नाम मिला।", "isCorrect": false}, {"id": "d", "body": "An old route long predates Sher Shah; he made it work through a system of upkeep and services.", "body_hi": "पुराना मार्ग शेरशाह से बहुत पहले का है; उन्होंने रख-रखाव और सेवाओं से उसे काम का बनाया।", "isCorrect": true}]'::jsonb,2.5,0.83,'The passage describes what Sher Shah did for the road and then corrects a common simplification: the route is far older and was rebuilt by many, and his real contribution was the system of upkeep and services. It says a highway already ran along the route in Mauryan times, so he did not build it from nothing; the British named the road but did not first build it; and the coin is mentioned in passing, not as his chief achievement.','परिच्छेद बताता है कि शेरशाह ने सड़क के लिए क्या किया और फिर एक आम सरलीकरण को सुधारता है: मार्ग कहीं पुराना है और अनेक ने उसका पुनर्निर्माण किया, और उनका वास्तविक योगदान रख-रखाव और सेवाओं की व्यवस्था थी। वह कहता है कि मौर्य काल में ही इस मार्ग पर एक राजमार्ग था, इसलिए उन्होंने उसे शून्य से नहीं बनाया; अंग्रेज़ों ने सड़क का नाम रखा पर उसे पहले नहीं बनाया; और सिक्के का उल्लेख प्रसंगवश है, उनकी मुख्य उपलब्धि के रूप में नहीं।','csat-l4-s03-rc-p05-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Specific Detail','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In the five years of his rule, from 1540 to 1545, Sher Shah Suri rebuilt and extended the great road that ran from Bengal across the plains to the north-west. Along it he set up sarais, rest houses for travellers at regular stages, dug wells and planted shade trees; the sarais also served as stations for a mounted postal service that carried news and orders quickly across the kingdom. He is remembered too for issuing a silver coin, the rupiya, whose name survives in the rupee. It is easy to credit the road to one ruler. In fact a highway along much the same route already linked the cities of the plains in Mauryan times, and the Mughals and later the British, who named it the Grand Trunk Road, kept rebuilding it. What Sher Shah added was a system of upkeep and services that made the road work as an instrument of government.

According to the passage, which one of the following was NOT a purpose served by the sarais along the road?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1540 से 1545 तक के अपने पाँच वर्षों के शासन में शेरशाह सूरी ने उस महान सड़क का पुनर्निर्माण और विस्तार किया जो बंगाल से मैदानों को पार करती हुई उत्तर-पश्चिम तक जाती थी। उसके किनारे उन्होंने सरायें बनवाईं, यात्रियों के लिए नियमित पड़ावों पर विश्राम-गृह, कुएँ खुदवाए और छायादार पेड़ लगवाए; सरायें घुड़सवार डाक-सेवा के ठिकानों का भी काम करती थीं, जो समाचार और आदेश राज्य भर में तेज़ी से पहुँचाती थी। उन्हें चाँदी का एक सिक्का, रुपया, जारी करने के लिए भी याद किया जाता है, जिसका नाम ''रुपये'' में आज भी जीवित है। सड़क का श्रेय एक शासक को दे देना आसान है। वास्तव में लगभग इसी मार्ग पर एक राजमार्ग मौर्य काल में ही मैदानों के नगरों को जोड़ता था, और मुग़ल और बाद में अंग्रेज़, जिन्होंने उसे ग्रैंड ट्रंक रोड नाम दिया, उसका पुनर्निर्माण करते रहे। शेरशाह ने जो जोड़ा वह रख-रखाव और सेवाओं की एक व्यवस्था थी जिसने सड़क को शासन के एक साधन के रूप में काम करने योग्य बनाया।

परिच्छेद के अनुसार, निम्नलिखित में से कौन-सा उद्देश्य सड़क के किनारे की सरायों से पूरा नहीं होता था?','{"craft": "precision", "csat_set": "csat-l4-s03", "passage_group": "csat-l4-s03-p05", "csat_order": 35}'::jsonb,'[{"id": "a", "body": "Giving travellers a place to rest at regular stages of the journey", "body_hi": "यात्रा के नियमित पड़ावों पर यात्रियों को विश्राम का स्थान देना", "isCorrect": false}, {"id": "b", "body": "Minting the silver coins that Sher Shah issued", "body_hi": "शेरशाह द्वारा जारी चाँदी के सिक्के ढालना", "isCorrect": true}, {"id": "c", "body": "Serving as stations for a mounted postal service", "body_hi": "घुड़सवार डाक-सेवा के ठिकानों का काम करना", "isCorrect": false}, {"id": "d", "body": "Helping news and orders travel quickly across the kingdom", "body_hi": "समाचारों और आदेशों को राज्य भर में तेज़ी से पहुँचाने में सहायता करना", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage says the sarais were rest houses for travellers and also served as stations for the mounted postal service carrying news and orders. Minting the rupiya is mentioned separately, as something Sher Shah did, not as a use of the sarais.','परिच्छेद कहता है कि सरायें यात्रियों के लिए विश्राम-गृह थीं और समाचार व आदेश ले जाने वाली घुड़सवार डाक-सेवा के ठिकानों का भी काम करती थीं। रुपया ढालने का उल्लेख अलग से है, शेरशाह के एक काम के रूप में, सरायों के उपयोग के रूप में नहीं।','csat-l4-s03-rc-p05-what-the-sarais-did-not-do','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
